package com.anamcara.controller;
import com.anamcara.model.Appointment;import com.anamcara.repository.AppointmentRepository;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import software.amazon.awssdk.regions.Region;import software.amazon.awssdk.services.dynamodb.DynamoDbClient;import software.amazon.awssdk.services.dynamodb.model.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/appointments")public class AdminAppointmentDeleteController{private final AppointmentRepository repository;private final DynamoDbClient db;private final String table;public AdminAppointmentDeleteController(AppointmentRepository repository,@Value("${aws.region}")String region,@Value("${app.dynamodb.table}")String table){this.repository=repository;this.db=DynamoDbClient.builder().region(Region.of(region)).build();this.table=table;}
@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable String id){Appointment a=repository.findAll().stream().filter(x->id.equals(x.id)).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Appointment not found."));List<TransactWriteItem>writes=new ArrayList<>();writes.add(TransactWriteItem.builder().delete(Delete.builder().tableName(table).key(Map.of("id",s(id))).conditionExpression("attribute_exists(id)").build()).build());try{LocalDateTime start=LocalDateTime.parse(a.preferredDate+"T"+a.preferredTime);for(int minute=0;minute<60;minute++){LocalDateTime point=start.plusMinutes(minute);String slotId="SLOT#"+point.toLocalDate()+"#"+point.toLocalTime();writes.add(TransactWriteItem.builder().delete(Delete.builder().tableName(table).key(Map.of("id",s(slotId))).conditionExpression("attribute_not_exists(id) OR appointmentId = :appointmentId").expressionAttributeValues(Map.of(":appointmentId",s(id))).build()).build());}}catch(DateTimeException ignored){}db.transactWriteItems(TransactWriteItemsRequest.builder().transactItems(writes).build());}
private AttributeValue s(String value){return AttributeValue.builder().s(value).build();}}
